"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[8704],{8039(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>o,default:()=>d,frontMatter:()=>r,metadata:()=>a,toc:()=>c});var i=n(4848),s=n(8453);const r={title:"The Standard Operating Procedure for Killing Innovation",date:new Date("2026-07-02T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"ai-industry-critique",article_tags:{zh:["\u5275\u65b0","\u904a\u6232\u7522\u696d","\u8cc7\u672c\u904b\u4f5c","\u6548\u7387\u512a\u5316"],en:["innovation","game-industry","capitalism","efficiency-optimization"]},keywords:["killing innovation","standard operating procedure","games industry","capital","optimization"],summary:"The same script\u2014when capital learns how to kill innovation, every industry becomes the games industry.",status:"published",reading_time:5,sidebar_position:2,description:"The same script\u2014when capital learns how to kill innovation, every industry becomes the games industry."},o="The Standard Operating Procedure for Killing Innovation",a={id:"TechNotes/\u6bba\u6b7b\u5275\u65b0\u7684\u6a19\u6e96\u4f5c\u696d\u7a0b\u5e8f",title:"The Standard Operating Procedure for Killing Innovation",description:"The same script\u2014when capital learns how to kill innovation, every industry becomes the games industry.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/TechNotes/\u6bba\u6b7b\u5275\u65b0\u7684\u6a19\u6e96\u4f5c\u696d\u7a0b\u5e8f.md",sourceDirName:"TechNotes",slug:"/TechNotes/\u6bba\u6b7b\u5275\u65b0\u7684\u6a19\u6e96\u4f5c\u696d\u7a0b\u5e8f",permalink:"/en/docs/TechNotes/\u6bba\u6b7b\u5275\u65b0\u7684\u6a19\u6e96\u4f5c\u696d\u7a0b\u5e8f",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:2,frontMatter:{title:"The Standard Operating Procedure for Killing Innovation",date:"2026-07-02T00:00:00.000Z",lang:"en",section:"sober-record",topic:"ai-industry-critique",article_tags:{zh:["\u5275\u65b0","\u904a\u6232\u7522\u696d","\u8cc7\u672c\u904b\u4f5c","\u6548\u7387\u512a\u5316"],en:["innovation","game-industry","capitalism","efficiency-optimization"]},keywords:["killing innovation","standard operating procedure","games industry","capital","optimization"],summary:"The same script\u2014when capital learns how to kill innovation, every industry becomes the games industry.",status:"published",reading_time:5,sidebar_position:2,description:"The same script\u2014when capital learns how to kill innovation, every industry becomes the games industry."},sidebar:"docs",previous:{title:'Did Jensen Huang Say "Liberal Arts Students Won"? You Got Fooled by the Clickbait.',permalink:"/en/docs/TechNotes/NvidaAllInPodcast"},next:{title:"Not a Transformation, But a Contraction: Another Way to Read the AI Job Wave",permalink:"/en/docs/TechNotes/20260409AIJobWave"}},h={},c=[{value:"I. How a Studio Dies",id:"i-how-a-studio-dies",level:2},{value:"II. The Structure of the Script",id:"ii-the-structure-of-the-script",level:2},{value:"III. Different Industry, Same Script",id:"iii-different-industry-same-script",level:2},{value:"IV. This Time Is Different\u2014Because the Soil Itself Has Been Turned Over",id:"iv-this-time-is-differentbecause-the-soil-itself-has-been-turned-over",level:2},{value:"V. The Only Character Not Written into the Script",id:"v-the-only-character-not-written-into-the-script",level:2}];function l(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",img:"img",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"the-standard-operating-procedure-for-killing-innovation",children:"The Standard Operating Procedure for Killing Innovation"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"The Same Script\u2014When Capital Learns How to Kill Innovation, Every Industry Becomes the Games Industry"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(8078).A+"",width:"1024",height:"1536"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"i-how-a-studio-dies",children:"I. How a Studio Dies"}),"\n",(0,i.jsx)(t.p,{children:"The opening of the story is always moving."}),"\n",(0,i.jsx)(t.p,{children:'Three people in a garage write a game, with no marketing budget and no publisher, climbing the Steam charts purely on player word-of-mouth. The media packages them with words like "dream" and "passion," and investors start knocking on the door.'}),"\n",(0,i.jsx)(t.p,{children:"Then the story enters the second act."}),"\n",(0,i.jsx)(t.p,{children:'A major publisher acquires the studio. The press release headline reads "Joining Forces." The founder receives a life-changing sum of money in exchange for a three-year lock-in contract and a Vice President title. In the first year, he can still decide the direction of the game. In the second year, the higher-ups start sending people to "assist" with product decisions, and KPIs shift from "player experience" to "monthly active users" and "ARPU." In the third year, the contract expires, and he leaves.'}),"\n",(0,i.jsx)(t.p,{children:'Or perhaps he doesn\'t leave. He gets "restructured."'}),"\n",(0,i.jsx)(t.p,{children:'The studio doesn\'t close down. It remains, carrying the same brand name, but the people sitting inside are completely different. Designers are replaced by data analysts, programmers are replaced by platform integration engineers, and the producer is replaced by a "Director of Operations." Games keep coming out: sequels, DLCs, battle passes, and limited-time events. Every quarterly financial report looks beautiful.'}),"\n",(0,i.jsx)(t.p,{children:"But that thing that kept players glued to their screens at 3 AM, unable to bring themselves to shut it off\u2014it's gone."}),"\n",(0,i.jsx)(t.p,{children:'No one killed it. It was simply "optimized."'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"ii-the-structure-of-the-script",children:"II. The Structure of the Script"}),"\n",(0,i.jsx)(t.p,{children:"If this were only the story of one studio, it would just be industry gossip. But the problem is, this script has been so successful that everyone is using it now."}),"\n",(0,i.jsx)(t.p,{children:"Its structure is remarkably concise:"}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Act I: Creation."})," Someone uses their own time, energy, and expertise to build something new. This thing has value because it solves a real problem or opens up a space others didn't see."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Act II: Harvest."}),' Capital enters the scene. Acquisition, investment, "strategic partnership"\u2014the label doesn\'t matter; what matters is the transfer of control. The creators get a payout and hand over the steering wheel.']}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Act III: Replacement."}),' The R&D staff are laid off; the monitoring staff are kept. "Innovation" becomes a column on a financial spreadsheet, to be filled in by the marketing department. Genuine engineering capability is outsourced, compressed, and standardized into interchangeable modules.']}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Act IV: Extraction."}),' The product doesn\'t stop, but it stops growing. It becomes a pipeline: users flow in, data flows out, and money flows up. All "updates" are designed to maintain the flow of this pipeline, not to make the product better.']}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Act V: Narrative."}),' Wall Street needs a story. So the company tells investors: we are using AI to boost efficiency, entering new markets, and positioning ourselves for the next decade. The stock price goes up. The CEO takes the stage to receive an award. Meanwhile, the three people from the garage have already updated their LinkedIn profiles to "Open to Work."']}),"\n",(0,i.jsx)(t.p,{children:"These five acts are not unique to the gaming industry."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"iii-different-industry-same-script",children:"III. Different Industry, Same Script"}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The Media Industry."})," Independent journalists and investigative reporting teams are laid off, replaced by SEO editors, traffic analysts, and automated content farm pipelines. Journalism isn't dead, but investigative reporting is. What survives are headlines that grab attention in three seconds, not journalists who spend three months chasing a lead."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The Software Industry."})," Microsoft's Windows has accumulated decades of technical debt\u2014the entire system is a shit-mountain of code stacked on top of itself. Intel's process technology has been left behind by AMD. But none of this hurts their balance sheets\u2014monopolistic positions let them keep harvesting through licensing, subscriptions, and ecosystem lock-in. The people who actually wrote the low-level engines are gone; what remains are people who can package \"Copilot\" as a revolution. The products haven't gotten better, but the subscription numbers have. Act IV of the script\u2014Extraction\u2014is executed here through the monthly subscription model: you don't need to make the software better; you just need to make sure the user can't leave."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The Education Industry."})," Taiwan's AI training ecosystem is the most naked version of this. Five thousand mentors teach you how to use tools, pass certification exams, and chase whatever's hot. No one teaches you how to define a problem worth solving. Education becomes a wholesale market for anxiety: certifications are the product, students are the users, and \"employment rate\" is the KPI written on the balance sheet. The kind of genuine mentorship that actually brings someone into the craft has been diluted to nothing by scale."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"The AI Industry Itself."}),' The most ironic part of this cycle: AI is being used to accelerate the execution of this very script. Enterprises use AI to cut R&D, monitor output, and compress the space for creation\u2014then tell you this is "AI transformation." The original ideal of AI was never to perpetually optimize efficiency in order to replace people, but to free up space and create more possibilities. But when the people who hold AI only care about the efficiency numbers on a balance sheet, AI itself gets contaminated into a sharper, more precise sickle.']}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"iv-this-time-is-differentbecause-the-soil-itself-has-been-turned-over",children:"IV. This Time Is Different\u2014Because the Soil Itself Has Been Turned Over"}),"\n",(0,i.jsx)(t.p,{children:'Whenever someone points out the cruelty of this script, the optimists trot out the same line: "New industries emerged after the Industrial Revolution, didn\'t they?"'}),"\n",(0,i.jsx)(t.p,{children:"The biggest problem with that statement isn't that it's wrong\u2014it's that it treats two completely different things as the same."}),"\n",(0,i.jsx)(t.p,{children:"The Industrial Revolution was destructive, but it simultaneously nurtured new spaces for creation. The power loom replaced hand weaving but opened the door to mechanical engineering. The steam engine phased out manual hauling but birthed railways, shipbuilding, and the entire modern logistics system. While old industries died, new ones truly grew from the soil\u2014because technology was open, knowledge was fluid, and anyone willing to learn and build could construct something new from the ruins."}),"\n",(0,i.jsx)(t.p,{children:"That is not the case today."}),"\n",(0,i.jsx)(t.p,{children:"Capital isn't just harvesting the fruits of innovation\u2014it is uprooting the whole plant, turning over the soil itself."}),"\n",(0,i.jsxs)(t.p,{children:["The first cut: laying off the people who do R&D. Independent studios are bought and then hollowed out; the people who build engines are replaced by people who track metrics. Tango Gameworks made ",(0,i.jsx)(t.em,{children:"Hi-Fi Rush"})," and was shut down three months later. Arkane Austin made ",(0,i.jsx)(t.em,{children:"Prey"})," and was cut in the same wave. The creators weren't weeded out by the market\u2014they were killed by the very people who acquired them."]}),"\n",(0,i.jsx)(t.p,{children:"The second cut: using closed source, platform lock-in, and regulation to block future creators at the gate. NVIDIA's CUDA uses ecosystem lock-in to make sure all AI researchers can't leave its hardware\u2014not because there are no alternatives, but because a decade's worth of toolchains, libraries, and teaching materials have all grown on CUDA; switching platforms means starting from zero. Patent walls and API lockdowns mean independent developers can't even reach the starting line. This isn't \"market competition\"\u2014this is building a wall at the entrance."}),"\n",(0,i.jsx)(t.p,{children:"When both cuts land together, the result is this: old industries die, and the soil from which new industries could grow is systematically compressed. It's not that there are zero cracks\u2014the open-source community, the corners where indie developers work, things are still growing there\u2014but those cracks are what slipped through the script's net, not part of its design. Within the territory this script covers, the space for creation is being methodically sealed shut."}),"\n",(0,i.jsx)(t.p,{children:"Using the Industrial Revolution as an analogy for today is like treating an era that tore down houses while building new ones as the same thing as an era that tears down houses and then dynamites the foundations."}),"\n",(0,i.jsxs)(t.p,{children:['So the question isn\'t "When will new industries appear?" The question is: ',(0,i.jsx)(t.strong,{children:"As this script's reach keeps expanding, how much longer can those cracks hold?"})]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"v-the-only-character-not-written-into-the-script",children:"V. The Only Character Not Written into the Script"}),"\n",(0,i.jsx)(t.p,{children:'The reason this script can play out again and again is that it writes everyone into its own narrative: creators are "acquisition targets," engineers are "costs to be optimized," users are "quantifiable traffic," investors are "an audience that needs to be fed stories." Everyone has a role, and every role has its scripted way off the stage.'}),"\n",(0,i.jsx)(t.p,{children:"The only character not written in this script is the one who refuses to take the stage."}),"\n",(0,i.jsx)(t.p,{children:'Not because they lack ability, but because they refuse to hand over their creations to be "optimized." They choose to build things at their own pace, in their own space\u2014not to be acquired, not to boost financial reports, but because the thing itself deserves to exist.'}),"\n",(0,i.jsx)(t.p,{children:'This choice is not romantic. Its costs are concrete: no salary security, no platform traffic, no big-company name to stand behind. But its one advantage is real\u2014what you build is yours, and it won\'t be "restructured" away one day.'}),"\n",(0,i.jsx)(t.p,{children:"It is not an easy path."}),"\n",(0,i.jsx)(t.p,{children:"But it is the only path outside the script."})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},8078(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/ChatGPT Image 2026\u5e747\u67082\u65e5 \u4e0a\u534809_39_53-b1ce64a466cc0e4eb1e1d8196e2179b4.png"},8453(e,t,n){n.d(t,{R:()=>o,x:()=>a});var i=n(6540);const s={},r=i.createContext(s);function o(e){const t=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(r.Provider,{value:t},e.children)}}}]);